+
+export type JevEvaluationErrorCode =
+  | 'timeout'
+  | 'authentication'
+  | 'rate_limit'
+  | 'model_unavailable'
+  | 'invalid_response'
+  | 'service_unavailable'
+  | 'request_failed';
+
+export class JevEvaluationError extends Error {
+  readonly code: JevEvaluationErrorCode;
+
+  constructor(code: JevEvaluationErrorCode, message: string) {
+    super(message);
+    this.name = 'JevEvaluationError';
+    this.code = code;
+  }
+}
